<?php session_start();$_SESSION['redirect_url']=$_SERVER['REQUEST_URI'];if(!isset($_SESSION['loggedin'])||$_SESSION['loggedin']!==true){header("Location: ../login.php");exit;}if($_SERVER["REQUEST_METHOD"]=="POST"){$title=$_POST['title'];$description=$_POST['description'];$targetDirectory="../postimages/";$targetFile=$targetDirectory.basename($_FILES["image"]["name"]);$uploadOk=1;$imageFileType=strtolower(pathinfo($targetFile,PATHINFO_EXTENSION));if(isset($_POST["submit"])){$check=getimagesize($_FILES["image"]["tmp_name"]);if($check===false){$uploadOk=0;$errorMessage="File is not an image.";}}if(file_exists($targetFile)){$uploadOk=0;$errorMessage="Sorry, file already exists.";}if($imageFileType!="jpg"&&$imageFileType!="png"&&$imageFileType!="jpeg"&&$imageFileType!="gif"){$uploadOk=0;$errorMessage="Sorry, only JPG, JPEG, PNG & GIF files are allowed.";}if($uploadOk==0){$errorMessage="Sorry, your file was not uploaded.";}else{if(move_uploaded_file($_FILES["image"]["tmp_name"],$targetFile)){require_once '../credentials.php';$conn=new mysqli($dbHost,$dbUsername,$dbPassword,$dbName);if($conn->connect_error){die("Connection failed: ".$conn->connect_error);}$stmt=$conn->prepare("INSERT INTO blog_posts (title, description, image) VALUES (?, ?, ?)");$stmt->bind_param("sss",$title,$description,$targetFile);if($stmt->execute()){$successMessage="Blog post added successfully.";$title="";$description="";}else{$errorMessage="Failed to add blog post.";}$stmt->close();$conn->close();}else{$errorMessage="Sorry, there was an error uploading your file.";}}} ?><?php include '../Header.php'; ?><div class="ttm-page-title-row"><div class="ttm-bg-layer ttm-page-title-row-bg-layer"></div><div class="container"><div class="row"><div class="text-center col-md-12"><div class="ttm-textcolor-white title-box"><div class="ttm-textcolor-white page-title-heading"><h2 class="title">Add Blog Post</h2></div><div class="breadcrumb-wrapper"><span><a href="/"title="Homepage"><i class="ti ti-home"></i> Home </a></span><span class="ttm-bread-sep">: : </span><span><span class="ttm-textcolor-skincolor">Add Blog Post</span></span></div></div></div></div></div></div><section class="error-404"><header class="text-center section-title"><h5>Add Blog Post</h5></header><div class="container pb-4"><div class="row"><div class="col-md-12"><?php if(!empty($errorMessage)): ?><div class="alert mt-3 alert-danger"><?php echo $errorMessage; ?></div><?php endif; ?><?php if(!empty($successMessage)): ?><div class="alert mt-3 alert-success"><?php echo $successMessage; ?></div><?php endif; ?><div class="row-title style4"><form action="addpost"enctype="multipart/form-data"method="POST"><div class="form-group text-left"><label for="title">Title:</label> <input name="title"class="form-control"value="<?php echo htmlspecialchars($title); ?>"id="title"required></div><div class="form-group text-left"><label for="description">Description:</label> <textarea class="form-control"id="description"name="description"required><?php echo isset($description)?htmlspecialchars($description):''; ?>



